<?php use Dilemma\Views; use Dilemma\Connections; ?>
<section class="reading"><h1><?= $t('authorize') ?></h1><h2><?= $e($authorization['client']['name']) ?></h2><p><?= $t('authorize_intro') ?></p><p><code><?= $e($authorization['redirect_uri']) ?></code></p><ul><li><?= $t('read_scope') ?></li><?php if (str_contains($authorization['scope'], Connections::WRITE)): ?><li><?= $t('write_scope') ?></li><?php endif; ?></ul><p><?= $t('human_boundary') ?></p>
<?= Views::form('/api/oauth/authorize', 'oauth') ?><?php foreach (['client_id', 'redirect_uri', 'response_type', 'code_challenge', 'code_challenge_method', 'resource', 'scope', 'state'] as $field) echo Views::hidden($field, $_GET[$field] ?? ($field === 'scope' ? Connections::READ : '')); ?><?= Views::hidden('approve', 'true') ?><?= Views::submit('authorize') ?><button type="button" class="text-button" data-oauth-deny><?= $t('deny') ?></button></form></section>
